section.sourcecode:
; ===================================================================== ; DTN BASKET PROTOCOL GRAMMAR (RFC 8610) ; =====================================================================
protocol-version = 1 coap-status-code = uint .size 1 ; CoAP status codes (RFC 7252)
; --------------------------------------------------------------------- ; 1. REQUEST BASKET (BASKET REQUEST) ; ---------------------------------------------------------------------
basket-request = { ? -1 => uint, ; Experimentation tag (e.g., 44444) 0 => uint, ; Protocol version (protocol-version = 1) 1 => text / bytes, ; Unique identifier of the request (req_id) ? 2 => text, ; Optional reply destination (reply_to EID) ? 3 => uint, ; Default lifetime of response bundles (ms/s) 4 => [* request-item] ; Array of items ordered by priority }
request-item = { 0 => uint .default 0, ; Operation: 0=GET, 1=CHECK, 2=SEARCH, 3=CANCEL, 4=LIST 1 => text, ; URI / URN / CID / Tag ? 2 => uint, ; Maximum accepted size in octets (max_size) ? 3 => [* (uint / text)],; Accepted formats (default = */*) ? 4 => [* bytes], ; Truncated hashes already owned (have_hashes) ? 5 => uint, ; POSIX timestamp (if_modified_since) ? 6 => uint ; Lifetime override for the response of this item (ms/s) }
; --------------------------------------------------------------------- ; 2. METADATA APPLICATION RESPONSE (BASKET RESPONSE) ; ---------------------------------------------------------------------
basket-response = { ? -1 => uint, ; Experimentation tag (e.g., 44444) 0 => uint, ; Protocol version (protocol-version = 1) 1 => text / bytes, ; Original request identifier (req_id) 2 => [* item-response] ; Array of results per item }
item-response = { 0 => uint, ; Item index in the original basket (item_idx). Note: Multiple item-responses may share the same item_idx (e.g. for SEARCH). 1 => coap-status-code, ; CoAP status code (RFC 7252) ? 2 => item-metadata, ; Metadata of the content bundle ? 3 => text ; Diagnostic message (if error status) }
item-metadata = { 0 => bytes, ; SHA-256 hash of the resource (correlation key) ? 1 => uint, ; Size of the resource in octets ? 2 => text, ; MIME type / Format (e.g., "text/markdown") ? 3 => text, ; Explicit URI / URN / CID of the resource ? 4 => uint ; POSIX timestamp of last modification }
